import tempfile
import torch
from topologies import Trainer, synth
root = tempfile.mkdtemp()
@synth.generator
def calibration_samples(ctx):
    logits = torch.randn(3, generator=ctx.rng.torch)
    shifted = logits + 0.3 * torch.randn(3, generator=ctx.rng.torch)
    return {"inputs": synth.Tensor(logits), "targets": int(shifted.argmax())}
ds = synth.Spec("dirichlet-calibration-data", generator=calibration_samples, size=12, splits={"train": 1.0}, seed=11, root=root, monitor="none").run()
train = ds.for_recipe("structured-objective", split="train")
class FixedLogitsCalibrator(torch.nn.Module):
    def __init__(self):
        super().__init__()
        self.weight = torch.nn.Parameter(torch.eye(3))
        self.bias = torch.nn.Parameter(torch.zeros(3))
    def forward(self, logits):
        return {"logits": logits, "weight": self.weight, "bias": self.bias}
model = FixedLogitsCalibrator()
trainer = Trainer(model, train, recipe="structured-objective", recipe_config={"loss": "dirichlet-calibration", "loss_kwargs": {"lambda": 0.01, "mu": 0.01}, "bindings": {"logits_or_prediction": {"output": "logits"}, "targets": {"batch": "targets"}, "weight": {"output": "weight"}, "bias": {"output": "bias"}}}, batch_size=4, max_epochs=1, device="cpu")
trainer.fit()
